import java.util.*;

public class Main {
    boolean isPowerOfThree(int n) {
        if (n < 1) {
            return false;                   // zero and negatives can never be powers of three
        }
        while (n > 1) {
            if (n % 3 != 0) {
                return false;                 // a remainder here breaks the chain of tripling
            }
            n /= 3;                           // keep dividing as long as it divides evenly
        }
        return true;                        // reached exactly 1 by only ever dividing cleanly
    }

    public static void main(String[] args) {
        int n = 27;
        Main solution = new Main();
        System.out.println(solution.isPowerOfThree(n));
    }
}

