import java.util.*;

public class Main {
    boolean isPowerOfThree(int n) {
        if (n < 1) {
            return false;
        }
        int power = (int) Math.round(Math.log(n) / Math.log(3)); // estimate the exponent using logarithms
        return Math.pow(3, power) == n;                             // verify the estimate exactly, log alone is not reliable
    }

    public static void main(String[] args) {
        int n = 27;
        Main solution = new Main();
        System.out.println(solution.isPowerOfThree(n));
    }
}

